import sys
from collections import OrderedDict
lines = sys.stdin.read().splitlines()
out = []
if lines:
    parts = lines[0].split()
    cap, m = int(parts[0]), int(parts[1])
    cache = OrderedDict()
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'PUT':
            k, v = int(cmd[1]), int(cmd[2])
            if k in cache: cache.move_to_end(k)
            cache[k] = v
            if len(cache) > cap: cache.popitem(last=False)
        elif cmd[0] == 'GET':
            k = int(cmd[1])
            if k in cache:
                cache.move_to_end(k)
                out.append(str(cache[k]))
            else: out.append('-1')
print(' '.join(out))
